func testConvenioBancarioToManyAddOpCVBPortadors(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a ConvenioBancario
	var b, c, d, e Portador

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, convenioBancarioDBTypes, false, strmangle.SetComplement(convenioBancarioPrimaryKeyColumns, convenioBancarioColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Portador{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, portadorDBTypes, false, strmangle.SetComplement(portadorPrimaryKeyColumns, portadorColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*Portador{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddCVBPortadors(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.CVBID, first.CVBID) {
			t.Error("foreign key was wrong value", a.CVBID, first.CVBID)
		}
		if !queries.Equal(a.CVBID, second.CVBID) {
			t.Error("foreign key was wrong value", a.CVBID, second.CVBID)
		}

		if first.R.CVB != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.CVB != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.CVBPortadors[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.CVBPortadors[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.CVBPortadors().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

